-- ============================================================================
-- 0. EXTENSÃO POSTGIS E DADOS BASE (CASO AINDA NÃO TENHA POPULADO AS FKs)
-- ============================================================================
CREATE EXTENSION IF NOT EXISTS postgis;







/*
 * ============================================================================
 * DESCRIÇÃO DA CARGA DE DADOS
 * ============================================================================
 * 1. Coordenadas Geográficas: Extraídas de mapeamento em arquivo GeoJSON 
 *
 * 2. Processamento SQL: As linhas de voo foram decompostas em 501 vértices 
 *    individuais (geometry Point, SRID 4326) e convertidas em comandos INSERT 
 *    via processamento automatizado assistido por IA.
 *
 * 3. Dados Sintéticos (Gerados por IA): Atributos de telemetria (timestamps, 
 *    perfis de velocidade de decolagem/aplicação/pouso e altitude MSL) e 
 *    registros cadastrais base foram gerados artificialmente para simular 
 *    operações reais de aviação agrícola.
 * ============================================================================
 */

